add_action( 'woocommerce_after_cart_item_name', 'perfectpixel_subscription_dates_cart', 10, 2 );
add_filter( 'woocommerce_checkout_cart_item_quantity', 'perfectpixel_subscription_dates_checkout', 10, 3 );

function perfectpixel_subscription_dates_html( $product ) {
	if ( ! class_exists( 'WC_Subscriptions_Product' ) || ! WC_Subscriptions_Product::is_subscription( $product ) ) {
		return '';
	}
	$format  = get_option( 'date_format' );
	$renewal = WC_Subscriptions_Product::get_first_renewal_payment_date( $product );
	$end     = WC_Subscriptions_Product::get_expiration_date( $product );

	$lines = array();
	if ( $renewal ) {
		$lines[] = esc_html( '{{renewal_label}}' ) . ' ' . esc_html( date_i18n( $format, strtotime( $renewal ) ) );
	}
	if ( $end ) {
		$lines[] = esc_html( '{{end_label}}' ) . ' ' . esc_html( date_i18n( $format, strtotime( $end ) ) );
	}
	return $lines ? '<div class="perfectpixel-subscription-dates" style="font-size:.85em;opacity:.8">' . implode( '<br>', $lines ) . '</div>' : '';
}

function perfectpixel_subscription_dates_cart( $cart_item, $cart_item_key ) {
	echo perfectpixel_subscription_dates_html( $cart_item['data'] ); // phpcs:ignore WordPress.Security.EscapeOutput -- Escaped in the helper.
}

function perfectpixel_subscription_dates_checkout( $quantity_html, $cart_item, $cart_item_key ) {
	return $quantity_html . perfectpixel_subscription_dates_html( $cart_item['data'] );
}
